  "output_head": "======= SHOW =======
<% content_for :title, "#{@quiz.title} · Quizzy" %>
<% active_count = @questions.count(&:active?) %>
<div class="breadcrumbs"><%= link_to "← All quizzes", moderate_root_path %></div>
<div class="page-head">
  <div>
    <h1><%= @quiz.title %></h1>
    <div class="meta mt-2">
      <%= active_count %> of <%= @questions.size %> questions active · <%= link_to "Settings", edit_moderate_quiz_path(@quiz) %>
    </div>
  </div>
  <div class="buttons">
    <%= link_to "Export", export_moderate_quiz_path(@quiz), class: "btn btn--ghost" %>
    <%= link_to "Preview", preview_moderate_quiz_path(@quiz), class: "btn btn--ghost" %>
  </div>
</div>

<section class="section mt-0">
  <div class="section-head">
    <h2>Questions</h2>
    <form action="<%= new_moderate_quiz_question_path(@quiz) %>" method="get">
      <button class="btn" type="submit">Add question</button>
    </form>
  </div>

  <% if @questions.empty? %>
    <div class="empty">No questions yet.</div>
  <% else %>
    <ul class="question-list">
      <% active_number = 0 %>
      <% @questions.each do |question| %>
        <% active_number += 1 if question.active? %>
        <li class="card question-item<%= " question-item--inactive" unless question.active? %>">
          <div class="question-item__num"><%= question.active? ? active_number : "—" %></div>
          <div>
            <div class="question-item__body"><%= question.body %></div>
            <ul class="question-item__options">
              <% question.ordered_options.each_with_index do |option, index| %>
                <li class="<%= "is-correct" if option.correct? %>"><%= option_letter(index) %>. <%= option.text %><% if option.correct? %><span class="correct-mark"> ✓</span><% end %></li>
              <% end %>
            </ul>
          </div>
          <div class="question-item__actions">
            <div class="buttons">
              <%= button_to "Move up", move_up_moderate_quiz_question_path(@quiz, question), method: :patch, class: "btn btn--ghost btn--sm" %>
              <%= button_to "Move down", move_down_moderate_quiz_question_path(@quiz, question), method: :patch, class: "btn btn--ghost btn--sm" %>
            </div>
            <%= form_with url: toggle_active_moderate_quiz_question_path(@quiz, question), method: :patch do %>
              <label class="checkbox">
                <%= hidden_field_tag "question[active]", "0", id: nil %>
                <%= check_box_tag "question[active]", "1", question.active?, id: "question_active_#{question.id}", onchange: "this.form.submit()" %>
                Active
              </label>
            <% end %>
            <div class="buttons">
              <%= link_to "Edit", edit_moderate_quiz_question_path(@quiz, question), class: "btn btn--sm" %>
              <%= button_to "Delete", moderate_quiz_question_path(@quiz, question), method: :delete, class: "btn btn--sm btn--danger", form: { onsubmit: "return confirm('Delete this question?');" } %>
            </div>
          </div>
        </li>
      <% end %>
    </ul>
  <% end %>
</section>
======= PREVIEW =======
<% content_for :title, "Preview · #{@quiz.title}" %>
<% content_for :full_bleed, "1" %>
<div class="preview-banner">
  <span>Preview mode · answers are not saved</span>
  <%= link_to "Back to quiz", moderate_quiz_path(@quiz) %>
</div>

<div class="play">
  <div class="play__top">
    <span class="logo play__logo"><span class="logo__mark">?</span>Quizzy</span>
    <span><%= @quiz.title %></span>
  </div>

  <div class="play__body play__body--top">
    <% if @phase == :empty %>
      <div class="play-question__body">No active questions.</div>
      <p class="play-lead">Turn a question on from the quiz page, then try the preview again.</p>
    <% elsif @phase == :score %>
      <div class="result-card">
        <div class="result-card__label">Preview complete</div>
        <div class="result-card__score">Score: <%= @score %>/<%= @total %></div>
      </div>
    <% else %>
      <div class="play-question__num">Question <%= @index + 1 %> of <%= @total %></div>
      <div class="play-question__body"><%= @question.body %></div>

      <% if @phase == :ask %>
        <div class="play-options">
          <% @question.ordered_options.each_with_index do |option, index| %>
            <%= button_to preview_moderate_quiz_path(@quiz), method: :post, class: "play-option", params: { step: "answer", index: @index, option_id: option.id, picks: @picks.join(",") } do %>
              <span class="play-option__letter" aria-hidden="true"><%= option_letter(index) %></span>
              <span class="play-option__title"><%= option.text %></span>
            <% end %>
          <% end %>
        </div>
      <% else %>
        <div class="play-options is-locked is-revealed">
          <% @question.ordered_options.each_with_index do |option, index| %>
            <div class="play-option<%= " is-correct" if option.correct? %><%= " is-picked" if @picked && option.id == @picked.id %>">
  ",
  "output_tail": "header__logo" href="<%= moderate_root_path %>"><span class="logo__mark">?</span>Quizzy</a>
  <span class="admin-header__tag">Moderator</span>
</header>
