.input:focus { border-color: var(--c-pink); box-shadow: 0 0 0 4px rgb(255 46 136 / 0.18); }
textarea.input { min-height: 110px; resize: vertical; }
.input--number { max-width: 140px; }

input[type="checkbox"] {
